You are given `row x col` grid representing a map where `grid[i][j] = 1` represents land and `grid[i][j] = 0` represents water.

Grid cells are connected horizontally/vertically (not diagonally). The `grid` is completely surrounded by water, and there is exactly one island (i.e., one or more connected land cells).

The island doesn't have "lakes", meaning the water inside isn't connected to the water around the island. One cell is a square with side length 1. The `grid` is rectangular, width and height don't exceed 100. Determine the perimeter of the island.

[**💻 Submit Code**](https://leetcode.com/problems/island-perimeter/description/)
<details><summary>Show Answer</summary>

```C++
class Solution {
public:
    bool isLand(vector<vector<int>>& grid, int x, int y){
        if( x < 0 or x >= grid.size() or y < 0 or y >= grid[0].size()  ) return false;
        return grid[x][y] == 1;
    }
    int islandPerimeter(vector<vector<int>>& grid) {
        int dx[] = {1,-1,0,0};
        int dy[] = {0,0,1,-1};
        int perimeter = 0;
        for(int ux = 0; ux < grid.size(); ux ++){
            for(int uy = 0; uy < grid[ux].size(); uy ++){
                if( !isLand(grid, ux, uy) ) continue;
                for(int i = 0; i < 4; i ++) {
                    int vx = ux + dx[i];
                    int vy = uy + dy[i];
                    if( !isLand(grid, vx, vy) ) perimeter ++;
                }
            }
        }
        return perimeter;
    }
};
```
</details>

Given a string containing just the characters '(', ')', '{', '}', '[' and ']', determine if the input string is valid.

[**💻 Submit Code**](https://leetcode.com/problems/valid-parentheses/description/)

<details> <summary> Show Answer </summary>

```cpp
class Solution {
public:
    bool isValid(string s) {
        stack<char> st;

        for (int i = 0; i < s.length(); i++) {
            // if opening bracket, push to stack
            if (s[i] ==  '(' or s[i] == '{' or s[i] == '[') {
                st.push(s[i]);
            } else {
                // if stack is empty, then no matching opening bracket 
                if (st.empty()) {
                    return false;
                } else {
                    char tp = st.top();

                    // check for matching pairs
                    if ((s[i] == ')' and tp == '(') 
                        or (s[i] == '}' and tp == '{') 
                        or s[i] == ']' and tp == '[') {
                            st.pop();
                    }  else {
                        return false;
                    }
                }
            }
        }

        return st.empty(); // if stack is empty, all pairs matched
    }
};

```
</details>

Given an array of integers `nums` and an integer `target`, return the indices of the two numbers such that they add up to `target`.

[**💻 Submit Code**](https://leetcode.com/problems/two-sum/description/)
<details> <summary> Show Answer </summary> 

```cpp
class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> idx;  // stores number -> index
        idx.reserve(nums.size());     // reserve space to optimize rehashing

        vector<int> ans;

        for (int i = 0; i < (int)nums.size(); i++) {
            int need = target - nums[i]; // number we need to reach target

            // if the "need" is already in the map, we found the pair
            auto it = idx.find(need);
            if (it != idx.end()) {
                ans = {it->second, i}; // return indices of the pair
                break;
            }

            // otherwise, store current number with its index
            idx[nums[i]] = i;
        }

        return ans;
    }
};

```
</details>

