Reverse a given singly linked list.

[**💻 Submit Code**](https://leetcode.com/problems/reverse-linked-list/description/)

At first, I used extra memory to store the reversed array.

<details><summary>Show Answer</summary>

```cpp
class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        if (head == NULL || head->next == NULL)
            return head;

        int i;
        vector<int> v;
        ListNode* cur = head;
        while (cur != NULL) {
            v.push_back(cur->val);
            cur = cur->next;
        }

        i = v.size()-1;
        cur = head;
        while (head != NULL) {
            head->val = v[i];
            i--;
            head = head->next;
        }
        return cur;
    }
};
```
</details>

They told me not to use extra memory. So, I performed an in-place reversal of the linked list.

<details><summary>Show Answer</summary>

```cpp
class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        if (head == NULL || head->next == NULL)
            return head;

        ListNode* prev = NULL;
        while (head != NULL) {
            ListNode* tmp = head->next;
            head->next = prev;
            prev = head;
            head = tmp;
        }
        return prev;
    }
};
```
</details>

