    int covered = 0;
    int st = ranges[0].first;
    int en = ranges[0].second;
    for(int i=1;i<ranges.size();i++){
        if( ranges[i].first > en ) {
            covered += en - st;
            st = ranges[i].first;
            en = ranges[i].second;
